	parts := strings.Split(readLine(), " ")
	n := atoi(parts[0])
	t := atoi(parts[1])
	str := []rune(readLine())

	for i := 0; i < t; i++ {
		j := 0
		for j < n-1 {
			if str[j] == 'B' && str[j+1] == 'G' {
